    fn run(
        transform: &mut Transform,
        velocity: &mut Velocity,
        grounded: &mut Grounded,
        latch: &mut JumpLatch,
        intent: InputIntent,
        frames: usize,
    ) -> Vec<f32> {
        let mut trace = Vec::with_capacity(frames);
        for _ in 0..frames {
            plan_velocity(velocity, grounded, latch, intent);
            step_motion(transform, velocity, grounded, DT);
            trace.push(transform.translation.y);
        }
        trace
    }

