        assert!(moved > 90.0 && moved < 110.0, "30 frames at 200 px/s is 100 px, got {moved}");

        // Release: level 0 must zero the velocity on the very first frame.
        run(
            &mut transform,
            &mut velocity,
            &mut grounded,
            &mut latch,
            InputIntent {
                move_dir: 0,
                jump_pressed: false,
            },
            30,
        );
        assert_eq!(transform.translation.x, moved, "released input must freeze x");
        assert_eq!(velocity.x, 0.0);
    }

