    fn jump_rises_then_falls_and_lands() {
        let (mut transform, mut velocity, mut grounded, mut latch) = spawn_state();
        assert!(grounded.on_ground, "the player starts on the ground");

        let take_off_y = transform.translation.y;
        let mut trace = Vec::new();
        // Hold the press for a while: the latch makes it exactly one jump.
        for _ in 0..45 {
            plan_velocity(
                &mut velocity,
                &mut grounded,
                &mut latch,
                InputIntent {
                    move_dir: 0,
                    jump_pressed: true,
                },
            );
            let was_grounded = grounded.on_ground;
            step_motion(&mut transform, &mut velocity, &mut grounded, DT);
            if was_grounded {
                // The frame that consumed the press is the last grounded one.
                assert!(!grounded.on_ground, "take-off must clear the ground state");
            }
